import { createHash } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const paths = ["SKILL.md", "agents/openai.yaml", "references/workflow.md"];
const files = await Promise.all(paths.map(async (path) => {
  const content = await readFile(join(root, "skills/argon-memory", path), "utf8");
  return { path, content, sha256: createHash("sha256").update(content).digest("hex"), size_bytes: Buffer.byteLength(content) };
}));
const bundle = createHash("sha256").update(files.map(file => `${file.path}\0${file.sha256}`).join("\n")).digest("hex");
const source = `// Generated by scripts/generate-skill-bundle.mjs\n\nexport const PROJECT_MCP_SERVER_VERSION = "0.1.0";\nexport const PROJECT_SKILL_NAME = "argon-memory";\nexport const PROJECT_SKILL_VERSION = "0.1.0";\nexport const PROJECT_SKILL_BUNDLE_SHA256 = "${bundle}";\n\nexport type ProjectSkillFile = { path: string; content: string; sha256: string; size_bytes: number };\n\nconst FILES = ${JSON.stringify(files, null, 2)} as const;\n\nexport const PROJECT_SKILL_RELEASE_FILE_HASHES: Readonly<Record<string, Readonly<Record<string, string>>>> = Object.freeze({\n  "0.1.0": ${JSON.stringify(Object.fromEntries(files.map(file => [file.path, file.sha256])), null, 2)}\n});\n\nexport function getProjectSkillFiles(): ProjectSkillFile[] { return FILES.map(file => ({ ...file })); }\n`;
await writeFile(join(root, "src/client-skill-bundle.generated.ts"), source, "utf8");
